import {mirrorCases,createMirror,mirrorModel,changeMirror,aimMirror,mirrorGeometry,mirrorComparison,mirrorExample} from './mirror-paths-core.mjs';
import {mirrorCopy as copy,mirrorTitles,mirrorIncident,mirrorProposal,mirrorReference,mirrorTurn,mirrorFeedback} from './mirror-paths-content.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null,retireBinding=()=>{},stopBinding=()=>{};
export function resetMirrorPaths(){retireBinding();stopBinding();stopBinding=()=>{};visit=null;}
function current(book,owner){if(!visit||visit.notebook!==book||visit.explorerId!==owner){resetMirrorPaths();visit={notebook:book,explorerId:owner,caseId:null,cases:new Map(),comparison:false,marks:false,panels:{},example:false,frame:0};}return visit;}
const button=(action,label,disabled=false,extra='')=>`<button type="button" data-mirror-action="${action}"${disabled?' disabled':''} ${extra}>${esc(label)}</button>`;
const read=(text,extra='')=>`<p data-mirror-read ${extra}>${esc(text)}</p>`;
const panel=(v,key,title,text)=>`<details data-mirror-panel="${key}"${v.panels[key]?' open':''}><summary>${title}</summary>${read(text)}</details>`;
const catalog=id=>`<div class="mirror-catalog">${mirrorCases.map(c=>`<button type="button" data-mirror-start="${c.id}"${id===c.id?' aria-current="true"':''}>${mirrorTitles[c.id]}<span>Incoming angle ${c.incidence}°</span></button>`).join('')}</div>`;
const xy=p=>`${p.x},${p.y}`;
const point=(h,heading,r)=>({x:h.x+Math.cos(heading*Math.PI/180)*r,y:h.y+Math.sin(heading*Math.PI/180)*r});
function line(kind,start,end){return `<line data-mirror-line="${kind}" x1="${start.x}" y1="${start.y}" x2="${end.x}" y2="${end.y}"/>`;}
function arrow(kind,ray,h){if(!ray)return '';const r=kind==='incoming'?105:kind==='reference'?125:145,dx=ray.end.x-ray.start.x,dy=ray.end.y-ray.start.y,length=Math.hypot(dx,dy),u={x:dx/length,y:dy/length};const out=kind==='incoming'?-1:1,tip={x:h.x+out*u.x*r,y:h.y+out*u.y*r},base={x:tip.x-u.x*13,y:tip.y-u.y*13};return `<polygon data-mirror-arrow="${kind}" points="${xy(tip)} ${base.x-u.y*6},${base.y+u.x*6} ${base.x+u.y*6},${base.y-u.x*6}"/>`;}
function arc(h,heading,a,r,kind){if(!a)return '';const start=point(h,heading,r),end=point(h,heading+a,r),label=point(h,heading+a/2,r+8);return `<path class="mirror-arc mirror-${kind}" data-mirror-arc="${kind}" d="M${xy(start)} A${r} ${r} 0 0 ${a>0?1:0} ${xy(end)}"/><text class="mirror-angle-label" x="${label.x}" y="${label.y}" text-anchor="middle">${kind==='incoming'?'I':kind==='proposal'?'P':'R'} ${Math.abs(a)}°</text>`;}
function drawing(m,v,isExample=false){const g=isExample?m.geometry:mirrorGeometry(v.cases.get(v.caseId)),h=g.hit,normal=!isExample||m.showNormal,reference=isExample?m.showReference:v.comparison,proposal=isExample?m.showFalse:m.angle!==null;const title=`Mirror path board. ${isExample&&!m.showNormal?'The incoming arrow shows one selected path reaching the mirror.':mirrorIncident(m)} ${isExample?(m.showFalse?'Different proposal: 60° from the normal.':'Separate example.'):mirrorProposal(m)} ${mirrorTurn(m)}${reference?' '+mirrorReference(m):''}`;
 const markers=`<circle data-mirror-hit cx="${h.x}" cy="${h.y}" r="5"/><circle data-mirror-lamp cx="${g.lamp.x}" cy="${g.lamp.y}" r="11"/>${m.incidence===0||isExample?'':`<polygon data-mirror-target points="${g.guide.x},${g.guide.y-10} ${g.guide.x+10},${g.guide.y} ${g.guide.x},${g.guide.y+10} ${g.guide.x-10},${g.guide.y}"/>`}`;
 return `<svg data-mirror-board data-mirror-angle="${m.angle===null?'':m.angle}" data-mirror-turn="${m.turn}" viewBox="0 0 600 440" role="img" aria-label="${esc(title)}"><rect class="mirror-plot" x="1" y="1" width="598" height="438" rx="12"/>${g.hatches.map(mark=>`<line class="mirror-hatch" x1="${mark.start.x}" y1="${mark.start.y}" x2="${mark.end.x}" y2="${mark.end.y}"/>`).join('')}${line('mirror',g.mirrorStart,g.mirrorEnd)}${v.marks&&normal?Array.from({length:11},(_,i)=>{const a=(i-5)*15,p=point(h,m.normalHeading+a,191),q=point(h,m.normalHeading+a,202);return `<line class="mirror-tick" x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}"/>`;}).join(''):''}${line('incoming',g.incoming.start,g.incoming.end)}${reference&&g.reference?line('reference',g.reference.start,g.reference.end):''}${proposal&&g.proposal?line('proposal',g.proposal.start,g.proposal.end):''}${normal?line('normal',h,g.normalEnd):''}${normal?`<polyline class="mirror-square" points="${g.rightAngle.map(xy).join(' ')}"/>${arc(h,m.normalHeading,m.sourceSide*m.incidence,42,'incoming')}${proposal?arc(h,m.normalHeading,m.angle,60,'proposal'):''}${reference?arc(h,m.normalHeading,m.referenceAngle,78,'reference'):''}`:''}${arrow('incoming',g.incoming,h)}${reference?arrow('reference',g.reference,h):''}${proposal?arrow('proposal',g.proposal,h):''}${markers}<text x="18" y="29">${isExample?'Separate example':'Plan a reflected path'}</text><text x="18" y="408">● Lamp${isExample?'':m.incidence===0?' / return mark':'     ◇ Green guide mark'}</text><text x="18" y="431">● Hit point · brass line: mirror${normal?' · dashed guide: normal':''}</text></svg>`;
}
function readouts(m,v,example=false){return `<div class="mirror-readouts">${!example||m.showNormal?read(mirrorIncident(m)):''}${!example?read(mirrorProposal(m)):m.showFalse?read('Different proposal: 60° from the normal.'):''}${example?m.showNormal?read('Incoming angle: 30° from the normal; 60° from the surface. Normal and mirror meet at 90°.'): '':read('The normal meets the mirror at 90°.')}${m.incidence===0?read(copy.headOn):!example&&m.angle===0?read(copy.normalOverlap):!example&&m.angle===m.sourceSide*m.incidence?read(copy.incomingOverlap):''}${read(mirrorTurn(m))}${read(copy.back)}${read('Amber solid, I: Incoming path.' + (!example||m.showNormal?' Dark dashed: Normal guide.':'') + ((!example&&m.angle!==null)||m.showFalse?' Blue dashed, P: '+(example?'Different proposal.':'Proposed path.'):'') + ((example?m.showReference:v.comparison)?' Green solid, R: Reference path.':''))}${!example?read(copy.tap):''}</div>`;}
function comparison(v,m){if(!v.comparison)return '';const result=mirrorComparison(v.cases.get(v.caseId));return `<section class="mirror-comparison" id="mirror-comparison" tabindex="-1">${read(mirrorFeedback(m,result.kind),'data-mirror-feedback role="status"')}${read(mirrorReference(m),'data-mirror-reference')}${button('hide','Hide reference')}</section>`;}
function example(v){const m=mirrorExample(v.frame);return `<div data-mirror-view="example" data-mirror-frame="${v.frame}"><h2 id="mirror-heading" tabindex="-1" data-mirror-read>Show a separate example</h2>${read('This is a separate mirror picture. Your proposal stays as you left it.')}${drawing(m,v,true)}${readouts(m,v,true)}${m.showReference?read(mirrorReference(m),'data-mirror-reference'):''}${read(`Picture ${v.frame+1} of 5. ${copy.frames[v.frame]}`,'role="status" data-mirror-caption')}<nav class="mirror-actions" aria-label="Example pictures">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===4)}${button('back','Back to my picture')}</nav>${hearButton('','Hear this picture')}</div>`;}
function board(v){const m=mirrorModel(v.cases.get(v.caseId));return `<div data-mirror-view="case" data-mirror-case="${v.caseId}"><h2 id="mirror-heading" tabindex="-1" data-mirror-read>${mirrorTitles[v.caseId]}</h2>${read(v.caseId==='return'?copy.returnRequest:copy.request,'class="mirror-request"')}${drawing(m,v)}<div class="mirror-actions mirror-ray-actions" role="group" aria-label="Change the proposed ray">${m.hasProposal?`${button('ccw','Turn counterclockwise 15°',!m.canCCW)}${button('cw','Turn clockwise 15°',!m.canCW)}${button('flip','Flip across the normal',!m.canFlip)}${button('clear','Clear proposal')}`:button('add','Add a proposed ray')}${button('undo','Undo ray change',!m.canUndo)}</div>${m.hasProposal&&(!m.canCCW||!m.canCW)?read(copy.bound):''}${m.angle===0?read(copy.flipReason):''}${!m.canUndo?read(copy.undoReason):''}${readouts(m,v)}<div class="mirror-actions">${button('rotate','Turn whole picture a quarter turn clockwise (90°)')}${button('guide',v.marks?'Hide angle guide':'Show angle guide',false,`aria-pressed="${v.marks}"`)}${button('compare','Compare paths')}${button('example','Show a separate example')}${hearButton('','Hear this picture')}</div>${comparison(v,m)}${v.marks?read(copy.degree):''}${panel(v,'help','About the normal and angles',copy.normal+' '+copy.vocabulary+' '+copy.framing)}<details data-mirror-panel="chooser"${v.panels.chooser?' open':''}><summary>Choose another picture</summary>${catalog(v.caseId)}</details>${panel(v,'talk','Talk together',copy.talk)}</div>`;}
export function mirrorPathsPage(book,owner){const v=current(book,owner);return `<section class="mirror-page" data-mirror-root><header class="mirror-header"><nav aria-label="Nearby places"><a href="#loft/shadows">Shadow Theater</a><a href="#loft">Story Loft</a></nav><h1>${copy.title}</h1></header><div class="mirror-worktop">${v.example?example(v):v.caseId?board(v):`<div data-mirror-view="chooser"><h2 id="mirror-heading" tabindex="-1" data-mirror-read>${copy.chooser}</h2>${read(copy.introduction)}${read(copy.framing)}${catalog(null)}</div>`}${read(copy.visit,'class="mirror-visit"')}${panel(v,'grownup','For grown-ups',copy.grownUp)}</div></section>`;}
function bindingGuard(root,valid,stop){
 const controls=[root,...root.querySelectorAll('button,input,select,a,summary,details,svg[data-mirror-board]')].filter(n=>!n.closest?.('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const disconnect=()=>{if(!disconnected){disconnected=true;observer.disconnect();}};
 const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();disconnect();}});observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return {disconnect,accepts(node){audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(node)||node.disabled||retired.has(node))return false;const old=chains.get(node),now=chain(node);if(!old||old.length!==now.length||!old.every((n,i)=>n===now[i]))return false;for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;}};
}
function visibleNarration(root){return [...root.querySelectorAll('[data-mirror-read]')].filter(node=>{for(let p=node;p&&p!==root;p=p.parentElement){const css=getComputedStyle(p);if(p.hidden||p.inert||p.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility)||p.tagName==='DETAILS'&&!p.open)return false;}return node.getClientRects().length>0;}).map(n=>n.textContent.replace(/\s+/g,' ').trim()).join(' ');}
export function bindMirrorPaths(book,ctx){
 retireBinding();const root=document.querySelector('[data-mirror-root]');if(!root||!visit)return;
 const v=visit,owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,caseId=v.caseId,material=v.cases.get(caseId),bytes=JSON.stringify(material),exampleOpen=v.example,frame=v.frame,comparison=v.comparison,marks=v.marks,parent=root.parentNode;
 const live=()=>root.isConnected&&root.parentNode===parent&&document.querySelector('[data-mirror-root]')===root&&location.hash==='#loft/mirrors'&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook??book)===book&&(!ctx.isActive||ctx.isActive())&&(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)===owner&&visit===v&&v.notebook===book&&v.explorerId===owner&&v.caseId===caseId&&v.cases.get(caseId)===material&&JSON.stringify(material)===bytes&&v.example===exampleOpen&&v.frame===frame&&v.comparison===comparison&&v.marks===marks;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},guard=bindingGuard(root,live,stop);retireBinding=guard.disconnect;stopBinding=stop;
 for(const control of root.querySelectorAll('button,input,select,a,summary,details,svg[data-mirror-board]')){if(control.closest('.speech-controls,drawn-howto'))continue;for(const type of ['click','input','change','keydown'])control.addEventListener(type,event=>{if(!guard.accepts(control)){event.preventDefault();event.stopImmediatePropagation();}},{capture:true});}
 const redraw=(selector='#mirror-heading',fallback='[data-mirror-action="undo"]')=>{guard.disconnect();ctx.render();let target=document.querySelector(selector);if(!target||target.disabled||!target.getClientRects().length){selector=fallback;target=document.querySelector(selector);}if(!target||target.disabled||!target.getClientRects().length)selector='#mirror-heading';if(ctx.focus)ctx.focus(selector);else document.querySelector(selector)?.focus();};
 root.querySelectorAll('[data-mirror-panel]').forEach(p=>p.addEventListener('toggle',()=>{if(guard.accepts(p)&&v.panels[p.dataset.mirrorPanel]!==p.open){v.panels[p.dataset.mirrorPanel]=p.open;stop();}}));
 root.addEventListener('click',event=>{const b=event.target.closest('[data-speak]');if(!b||!root.contains(b)||b.closest('.speech-controls,drawn-howto'))return;if(!guard.accepts(b)){event.preventDefault();event.stopImmediatePropagation();return;}b.dataset.speak=visibleNarration(root);},{capture:true});
 root.querySelectorAll('[data-mirror-start]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b)||!mirrorCases.some(c=>c.id===b.dataset.mirrorStart))return;stop();v.caseId=b.dataset.mirrorStart;if(!v.cases.has(v.caseId))v.cases.set(v.caseId,createMirror(v.caseId));v.comparison=false;v.example=false;v.panels.chooser=false;redraw();}));
 const setMaterial=(next,action)=>{if(!next||next===material)return;stop();v.cases.set(caseId,next);if(action!=='rotate')v.comparison=false;redraw(`[data-mirror-action="${action}"]`,action==='add'?'[data-mirror-action="cw"]':action==='clear'?'[data-mirror-action="undo"]':action==='undo'&&!mirrorModel(next).hasProposal?'[data-mirror-action="add"]':action==='ccw'?'[data-mirror-action="cw"]':action==='cw'?'[data-mirror-action="ccw"]':'[data-mirror-action="undo"]');};
 root.querySelectorAll('[data-mirror-action]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b))return;const action=b.dataset.mirrorAction;
 if(action==='example'){stop();v.example=true;v.frame=0;redraw();return;}
 if(action==='back'&&exampleOpen){stop();v.example=false;redraw('[data-mirror-action="example"]');return;}
 if(['previous','next'].includes(action)&&exampleOpen){const next=frame+(action==='next'?1:-1);if(!mirrorExample(next))return;stop();v.frame=next;redraw(`[data-mirror-action="${next===4?'previous':next===0?'next':action}"]`);return;}
 if(exampleOpen||!material)return;
 if(action==='compare'){if(v.comparison)return;stop();v.comparison=true;redraw('#mirror-comparison');return;}
 if(action==='hide'){stop();v.comparison=false;redraw('[data-mirror-action="compare"]');return;}
 if(action==='guide'){stop();v.marks=!v.marks;redraw('[data-mirror-action="guide"]');return;}
 setMaterial(changeMirror(material,action),action);
 }));
 const svg=root.querySelector('svg[data-mirror-board]');svg?.addEventListener('click',event=>{if(!guard.accepts(svg)||exampleOpen||!material)return;let point;try{const ctm=svg.getScreenCTM();if(!ctm)return;point=new DOMPoint(event.clientX,event.clientY).matrixTransform(ctm.inverse());if(!Number.isFinite(point.x)||!Number.isFinite(point.y))return;}catch{return;}setMaterial(aimMirror(material,point.x,point.y),'aim');});
}
